  beforeEach(() => {
    vi.clearAllMocks();
    api.listTaskImages.mockResolvedValue({ images: [] });
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  const renderAttach = (props = {}) =>
    renderWithKainBain(
      <TaskImageAttach
