    const file = new File(['text'], 'notes.txt', { type: 'text/plain' });
    fireEvent.change(input, { target: { files: [file] } });

    await waitFor(() => expect(api.uploadTaskImage).not.toHaveBeenCalled());
    expect(onUploaded).not.toHaveBeenCalled();
